import random
import re
import statistics
import string
import time
from bisect import bisect
from collections import defaultdict
from enum import StrEnum, auto
from itertools import islice
from pathlib import Path
from typing import Iterable

from matplotlib import pyplot as plt
from tqdm import tqdm

from grqe.corpus import AnnotationsDir, Corpus
from grqe.type_definitions import Symbol

RANDOM = random.Random()


class RegexType(StrEnum):
    PREFIX = auto()
    SUFFIX = auto()
    INFIX = auto()


def regexes(chars: list[str]) -> Iterable[str]:
    while True:
        grain = RANDOM.choices(chars, k=int(RANDOM.expovariate(1)) + 1)
        grain = ''.join(grain)
        match RANDOM.choice(list(RegexType)):
            case RegexType.PREFIX:
                regex = f'{grain}.*'
            case RegexType.SUFFIX:
                regex = f'.*{grain}'
            case RegexType.INFIX:
                regex = f'.*{grain}.*'
        yield regex


class TestCase:
    feature: AnnotationsDir
    characters: list[str]

    def __init__(self, feature: AnnotationsDir):
        self.feature = feature
        all_chars = {char for s in self.feature.symbols._bytesarray for char in s.decode()}
        all_chars &= set(string.ascii_letters)
        self.characters = list(all_chars)

    def table_iter(self, regex: str) -> Iterable[Symbol]:
        pattern = re.compile(regex.encode())
        for i, symbol in enumerate(self.feature.symbols):
            if pattern.fullmatch(symbol):
                yield i

    def table_fullscan_starts(self, regex: str) -> Iterable[Symbol]:
        pattern = compile_regex(regex)
        symboltable = self.feature.symbols._bytesarray._rawdata
        starts = self.feature.symbols._bytesarray._starts

        for match in pattern.finditer(symboltable):
            yield bisect(starts, match.start() + 1)

    def table_fullscan_lazy(self, regex: str) -> Iterable[Symbol]:
        pattern = compile_regex(regex)

        symboltable = self.feature.symbols._bytesarray._rawdata
        for match in pattern.finditer(symboltable):
            bytestr = symboltable[match.start() + 1:match.end()]
            yield self.feature.symbols.to_symbol(bytestr)

    def table_fullscan_eager(self, regex: str) -> Iterable[Symbol]:
        pattern = compile_regex(regex)

        symboltable = self.feature.symbols._bytesarray._rawdata
        for bytestr in pattern.findall(symboltable):
            bytestr = bytestr[1:]
            yield self.feature.symbols.to_symbol(bytestr)


def compile_regex(regex: str) -> re.Pattern:
    regex = regex.replace('.', '[^\x00]')
    regex = f'\x00{regex}(?=\x00)'
    return re.compile(regex.encode())


def count_and_time(fct, inp) -> tuple[int, float]:
    before = time.perf_counter_ns()
    count = 0
    for _ in fct(inp):
        count += 1
    after = time.perf_counter_ns()
    return count, (after - before) / (1000 * 1000 * 1000)

def inspect(corpus: str, feature: str, regex: str):
    corpus_dir = Path('/home/niklas/encoded/')
    with Corpus(corpus, corpus_dir).lock() as corpus_instance:
        resolved_feature = corpus_instance.feature(feature)
        case = TestCase(resolved_feature)

        variants = {
            'table_iter': case.table_iter,
            'table_scan': case.table_fullscan_starts,
        }
        for name, fct in variants.items():
            print(name)
            for result in fct(regex):
                print(result)
            print()

def run_experiments(corpus: str, feature: str, iters: int, repeats: int):
    corpus_dir = Path('/home/niklas/encoded/')
    with Corpus(corpus, corpus_dir).lock() as corpus_instance:
        resolved_feature = corpus_instance.feature(feature)
        case = TestCase(resolved_feature)

        variants = {
            'table_iter': case.table_iter,
            'table_scan': case.table_fullscan_starts,
        }
        data_points = {
            key: [] for key in variants.keys()
        }

        samples = islice(regexes(case.characters), iters)
        for r in tqdm(samples, desc=f'{corpus}.{feature}', total=iters):
            try:
                for variant_name, variant in variants.items():
                    times_taken = []
                    for _ in range(repeats):
                        count, individual_time_taken = count_and_time(variant, r)
                        times_taken.append(individual_time_taken)

                    data_points[variant_name].append(
                        (count, statistics.mean(times_taken), r)
                    )
            except:
                pass
        return data_points


