def visualize_dataset(dataset):
    fig, ax = plt.subplots()

    for variant_name, measurements in dataset.items():
        X = [count for count, _, _ in measurements]
        Y = [duration for _, duration, _ in measurements]

        ax.scatter(X, Y, label=variant_name)

    ax.set_xlabel('# results')
    ax.set_ylabel('duration [s]')
    ax.set_xscale('log')
    ax.legend()
    plt.show()


def report_mismatches(dataset):
    normalized = defaultdict(dict)
    for variant_name, measurements in dataset.items():
        for count, _, regex in measurements:
            normalized[regex][variant_name] = count

    for regex, values in normalized.items():
        if len(set(values.values())) != 1:
            print(f'{regex} mismatches: ' +
                  ' | '.join(f'{var}: {count}' for var, count in values.items()))


